#include <stdio.h>
#include <string.h>
#include <ctype.h>
int main() {
    char s[1000];
    if (!fgets(s, sizeof(s), stdin)) return 0;
    int counts[256] = {0}, seen[256] = {0};
    int len = strlen(s);
    for (int i = 0; i < len; i++) {
        char c = tolower(s[i]);
        if (c != ' ' && c != '\n' && c != '\r') counts[(unsigned char)c]++;
    }
    int first = 1;
    for (int i = 0; i < len; i++) {
        char c = tolower(s[i]);
        if (c != ' ' && c != '\n' && c != '\r' && counts[(unsigned char)c] > 1 && !seen[(unsigned char)c]) {
            seen[(unsigned char)c] = 1;
            if (!first) putchar(' ');
            putchar(c); first = 0;
        }
    }
    putchar('\n');
    return 0;
}

