import sys
from collections import Counter
def main():
    s = sys.stdin.read().strip().lower()
    counts = Counter(c for c in s if c != " ")
    res = []
    seen = set()
    for c in s:
        if c != " " and counts[c] > 1 and c not in seen:
            seen.add(c)
            res.append(c)
    print(" ".join(res))
if __name__ == "__main__": main()

